'use strict';
(function(root){const content={"short": [{"id": "listen-short-01", "title": "Joining a repair workshop", "transcript": "Adviser: Riverside Repair Hub. How can I help?\n\nVisitor: I saw your Saturday workshop online. I have a lamp that flickers, and I wondered whether I could bring it. I have never repaired anything electrical before.\n\nAdviser: You certainly can. We work alongside visitors rather than taking items away and returning them later. You do the safe tasks yourself, with guidance. But this Saturday is fully booked. We have a cancellation on Sunday if that suits you.\n\nVisitor: Sunday is actually better. The website says the morning session starts at nine. Is that correct?\n\nAdviser: That was last month. Please arrive at ten; the volunteers use the first hour to set up the tables. We finish at one, but you do not need to stay for the whole session.\n\nVisitor: Good. Should I bring my own tools? I have a small screwdriver, although I am not sure it is the right size.\n\nAdviser: We provide tools. What we do need is the power cable that belongs to the lamp. People sometimes leave that at home, and then we cannot test the item properly. If the bulb is removable, leave it in place.\n\nVisitor: And is there a charge? I thought I saw fifteen pounds somewhere.\n\nAdviser: Fifteen pounds is the suggested donation for a completed repair. There is no booking fee. If we need a replacement part, we will explain its cost before ordering it, and you can decide whether to proceed.\n\nVisitor: That sounds fair. Where should I go when I arrive? The entrance on Market Street looks quite narrow.\n\nAdviser: That entrance is closed while the pavement is repaired. Use the garden gate behind the building. There is a sign beside it. Once inside, leave your name at reception; we will match you with a volunteer.\n\nVisitor: Lovely. Please book me in, then.", "segments": [{"speaker": "Adviser", "text": "Riverside Repair Hub. How can I help?"}, {"speaker": "Visitor", "text": "I saw your Saturday workshop online. I have a lamp that flickers, and I wondered whether I could bring it. I have never repaired anything electrical before."}, {"speaker": "Adviser", "text": "You certainly can. We work alongside visitors rather than taking items away and returning them later. You do the safe tasks yourself, with guidance. But this Saturday is fully booked. We have a cancellation on Sunday if that suits you."}, {"speaker": "Visitor", "text": "Sunday is actually better. The website says the morning session starts at nine. Is that correct?"}, {"speaker": "Adviser", "text": "That was last month. Please arrive at ten; the volunteers use the first hour to set up the tables. We finish at one, but you do not need to stay for the whole session."}, {"speaker": "Visitor", "text": "Good. Should I bring my own tools? I have a small screwdriver, although I am not sure it is the right size."}, {"speaker": "Adviser", "text": "We provide tools. What we do need is the power cable that belongs to the lamp. People sometimes leave that at home, and then we cannot test the item properly. If the bulb is removable, leave it in place."}, {"speaker": "Visitor", "text": "And is there a charge? I thought I saw fifteen pounds somewhere."}, {"speaker": "Adviser", "text": "Fifteen pounds is the suggested donation for a completed repair. There is no booking fee. If we need a replacement part, we will explain its cost before ordering it, and you can decide whether to proceed."}, {"speaker": "Visitor", "text": "That sounds fair. Where should I go when I arrive? The entrance on Market Street looks quite narrow."}, {"speaker": "Adviser", "text": "That entrance is closed while the pavement is repaired. Use the garden gate behind the building. There is a sign beside it. Once inside, leave your name at reception; we will match you with a volunteer."}, {"speaker": "Visitor", "text": "Lovely. Please book me in, then."}], "audio": "ielts-audio/listen-short-01.m4a", "questions": [{"id": "ls1-1", "type": "completion", "prompt": "The visitor will attend on _____. Write ONE WORD.", "answer": "Sunday", "maxWords": 1, "explanation": "Saturday is full; the visitor accepts Sunday.", "skill": "detail and spelling"}, {"id": "ls1-2", "type": "completion", "prompt": "Arrival time: _____ a.m. Write ONE WORD OR A NUMBER.", "answer": "10", "maxWords": 1, "explanation": "Nine was the old start time. The adviser corrects it to ten.", "skill": "detail and spelling", "acceptedAnswers": ["10", "ten"]}, {"id": "ls1-3", "type": "completion", "prompt": "The visitor must bring the lamp’s _____. Write NO MORE THAN TWO WORDS.", "answer": "power cable", "maxWords": 2, "explanation": "Tools are supplied, but the correct power cable is needed for testing.", "skill": "detail and spelling"}, {"id": "ls1-4", "type": "mcq", "prompt": "When will the visitor be told the price of a replacement part?", "options": ["Before the part is ordered", "After the repair is completed", "When paying the booking fee"], "answer": "Before the part is ordered", "explanation": "The adviser explicitly says the cost is explained before ordering.", "skill": "paraphrase and distractors"}, {"id": "ls1-5", "type": "completion", "prompt": "Visitors should enter through the _____. Write NO MORE THAN TWO WORDS.", "answer": "garden gate", "maxWords": 2, "explanation": "The Market Street entrance is closed; the garden gate is the alternative.", "skill": "detail and spelling"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 141.83, "audioLabel": "Prerecorded synthetic voices · Daniel (UK English) and Samantha (US English)", "audioPreparationSeconds": 20}, {"id": "listen-short-02", "title": "A museum after hours", "transcript": "Guide: Welcome to the Harbour Museum evening visit. This is a smaller tour than our daytime programme, so there will be plenty of time for questions. You may have noticed the new glass extension beside reception. It contains the shop and the education room; our first stop will be the older stone building, where the boats are displayed. Please follow the blue signs, rather than the green ones for the café.\n\nGuide: Photography is normally welcome. Tonight, however, one of the paintings in the upstairs gallery is on loan from a private owner. There is a small crossed-out camera symbol beside that painting. You can photograph the other objects, provided you turn off your flash. There is no general ban on phones, but please silence them so that everyone can hear.\n\nGuide: The main exhibition traces changes in working life along the coast. The large maps are useful, but I particularly recommend listening to the short interviews. They include people who worked on the ships and in the warehouses. Several describe the same event differently, which gives us an opportunity to discuss how memory shapes accounts of the past.\n\nGuide: At seven thirty we will pause for a demonstration of rope making. We originally planned this for the courtyard, but rain is forecast, so it will take place in the workshop. The workshop is through the double doors at the end of the boat hall. You can try the equipment afterwards; children must be accompanied by an adult.\n\nGuide: Finally, the museum closes at nine, half an hour later than usual. The café will still stop serving at eight, so order before then if you would like something hot. The shop stays open until closing time. Your ticket includes a return visit within a month: just keep the receipt. That return visit is during normal opening hours, and does not include another evening tour.", "segments": [{"speaker": "Guide", "text": "Welcome to the Harbour Museum evening visit. This is a smaller tour than our daytime programme, so there will be plenty of time for questions. You may have noticed the new glass extension beside reception. It contains the shop and the education room; our first stop will be the older stone building, where the boats are displayed. Please follow the blue signs, rather than the green ones for the café."}, {"speaker": "Guide", "text": "Photography is normally welcome. Tonight, however, one of the paintings in the upstairs gallery is on loan from a private owner. There is a small crossed-out camera symbol beside that painting. You can photograph the other objects, provided you turn off your flash. There is no general ban on phones, but please silence them so that everyone can hear."}, {"speaker": "Guide", "text": "The main exhibition traces changes in working life along the coast. The large maps are useful, but I particularly recommend listening to the short interviews. They include people who worked on the ships and in the warehouses. Several describe the same event differently, which gives us an opportunity to discuss how memory shapes accounts of the past."}, {"speaker": "Guide", "text": "At seven thirty we will pause for a demonstration of rope making. We originally planned this for the courtyard, but rain is forecast, so it will take place in the workshop. The workshop is through the double doors at the end of the boat hall. You can try the equipment afterwards; children must be accompanied by an adult."}, {"speaker": "Guide", "text": "Finally, the museum closes at nine, half an hour later than usual. The café will still stop serving at eight, so order before then if you would like something hot. The shop stays open until closing time. Your ticket includes a return visit within a month: just keep the receipt. That return visit is during normal opening hours, and does not include another evening tour."}], "audio": "ielts-audio/listen-short-02.m4a", "questions": [{"id": "ls2-1", "type": "mcq", "prompt": "Where will the tour go first?", "options": ["The glass extension", "The old stone building", "The café"], "answer": "The old stone building", "explanation": "The guide says the first stop is the older stone building.", "skill": "paraphrase and distractors"}, {"id": "ls2-2", "type": "mcq", "prompt": "What photography restriction applies tonight?", "options": ["No phones anywhere in the museum", "No photographs of one particular painting", "No photographs in the entire upstairs gallery"], "answer": "No photographs of one particular painting", "explanation": "Only one loaned painting must not be photographed; other objects can be photographed without flash.", "skill": "paraphrase and distractors"}, {"id": "ls2-3", "type": "mcq", "prompt": "Why does the guide recommend the interviews?", "options": ["They provide contrasting memories of shared events", "They contain more dates than the maps", "They explain how to build a boat"], "answer": "They provide contrasting memories of shared events", "explanation": "Different descriptions of the same event reveal how memory shapes accounts.", "skill": "paraphrase and distractors"}, {"id": "ls2-4", "type": "completion", "prompt": "The rope-making demonstration will take place in the _____. Write ONE WORD.", "answer": "workshop", "maxWords": 1, "explanation": "Rain has caused the demonstration to move from the courtyard to the workshop.", "skill": "detail and spelling"}, {"id": "ls2-5", "type": "completion", "prompt": "To use the return visit, visitors must keep the _____. Write ONE WORD.", "answer": "receipt", "maxWords": 1, "explanation": "The guide says to keep the receipt for the included return visit.", "skill": "detail and spelling"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 153.22, "audioLabel": "Prerecorded synthetic voice · Daniel (UK English)", "audioPreparationSeconds": 20}, {"id": "listen-short-03", "title": "Planning a campus survey", "transcript": "Maya: We need to finalise our survey about cycling to campus. My first idea was to ask whether people wanted more bicycle parking, but the tutor said that was too narrow.\n\nLeo: Right. We agreed to investigate what prevents students from cycling, whether they currently own a bicycle or not. Parking can be one factor, alongside traffic and travel distance.\n\nMaya: How should we recruit people? Sending the link to the cycling club would be quick.\n\nLeo: It would, but their members are probably more confident cyclists than the average student. Let us approach students at three different campus entrances instead. We should include morning and afternoon periods, because course timetables vary.\n\nMaya: Agreed. I tested the questionnaire on my flatmate. She understood most of it, but she could not answer the question asking whether her route was safe and convenient.\n\nLeo: Because a route might be one but not the other?\n\nMaya: Exactly. So I have divided that into two questions. She also thought the questionnaire was quite long, though she finished it in four minutes. I think that is acceptable.\n\nLeo: We will check the timing in the pilot. For the final question, I suggested asking people to rank possible improvements. The tutor warned that ranking six things might be demanding, especially on a small phone screen.\n\nMaya: Then ask them to choose the single improvement most likely to change their behaviour. It gives us a clearer priority. We can leave an optional comment box for explanations.\n\nLeo: Good. Who is doing what? I can create the online form tonight, but I have a laboratory class during tomorrow’s pilot.\n\nMaya: I will run the pilot with five volunteers. You can check whether the downloaded responses appear in the right columns before we launch. We should not start collecting the real data until we have both looked at the pilot results.\n\nLeo: Yes. Fixing a confusing question halfway through would make the early and later responses difficult to compare.", "segments": [{"speaker": "Maya", "text": "We need to finalise our survey about cycling to campus. My first idea was to ask whether people wanted more bicycle parking, but the tutor said that was too narrow."}, {"speaker": "Leo", "text": "Right. We agreed to investigate what prevents students from cycling, whether they currently own a bicycle or not. Parking can be one factor, alongside traffic and travel distance."}, {"speaker": "Maya", "text": "How should we recruit people? Sending the link to the cycling club would be quick."}, {"speaker": "Leo", "text": "It would, but their members are probably more confident cyclists than the average student. Let us approach students at three different campus entrances instead. We should include morning and afternoon periods, because course timetables vary."}, {"speaker": "Maya", "text": "Agreed. I tested the questionnaire on my flatmate. She understood most of it, but she could not answer the question asking whether her route was safe and convenient."}, {"speaker": "Leo", "text": "Because a route might be one but not the other?"}, {"speaker": "Maya", "text": "Exactly. So I have divided that into two questions. She also thought the questionnaire was quite long, though she finished it in four minutes. I think that is acceptable."}, {"speaker": "Leo", "text": "We will check the timing in the pilot. For the final question, I suggested asking people to rank possible improvements. The tutor warned that ranking six things might be demanding, especially on a small phone screen."}, {"speaker": "Maya", "text": "Then ask them to choose the single improvement most likely to change their behaviour. It gives us a clearer priority. We can leave an optional comment box for explanations."}, {"speaker": "Leo", "text": "Good. Who is doing what? I can create the online form tonight, but I have a laboratory class during tomorrow’s pilot."}, {"speaker": "Maya", "text": "I will run the pilot with five volunteers. You can check whether the downloaded responses appear in the right columns before we launch. We should not start collecting the real data until we have both looked at the pilot results."}, {"speaker": "Leo", "text": "Yes. Fixing a confusing question halfway through would make the early and later responses difficult to compare."}], "audio": "ielts-audio/listen-short-03.m4a", "questions": [{"id": "ls3-1", "type": "mcq", "prompt": "What is the agreed aim of the survey?", "options": ["To choose new bicycle parking sites", "To identify barriers to cycling", "To estimate bicycle ownership"], "answer": "To identify barriers to cycling", "explanation": "They broaden the aim from parking to factors preventing cycling.", "skill": "paraphrase and distractors"}, {"id": "ls3-2", "type": "mcq", "prompt": "Why do they reject recruiting only from the cycling club?", "options": ["Members may not represent typical students", "The club has too few members", "Members have already completed the survey"], "answer": "Members may not represent typical students", "explanation": "Club members are likely to be more confident cyclists; the concern is sampling bias.", "skill": "paraphrase and distractors"}, {"id": "ls3-3", "type": "mcq", "prompt": "Why was one survey question divided into two?", "options": ["It combined two qualities that could differ", "It contained unfamiliar vocabulary", "It took too long to read aloud"], "answer": "It combined two qualities that could differ", "explanation": "A route may be safe but inconvenient, or convenient but unsafe.", "skill": "paraphrase and distractors"}, {"id": "ls3-4", "type": "mcq", "prompt": "What will respondents do with the proposed improvements?", "options": ["Rank all six from best to worst", "Choose the one most likely to affect their behaviour", "Give every improvement a numerical score"], "answer": "Choose the one most likely to affect their behaviour", "explanation": "They replace ranking six items with selecting one priority.", "skill": "paraphrase and distractors"}, {"id": "ls3-5", "type": "mcq", "prompt": "What will Leo do before the launch?", "options": ["Conduct the pilot interviews", "Check the exported responses", "Write the final report"], "answer": "Check the exported responses", "explanation": "Maya will run the pilot; Leo will check the downloaded data columns.", "skill": "paraphrase and distractors"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 155.45, "audioLabel": "Prerecorded synthetic voices · Daniel (UK English) and Samantha (US English)", "audioPreparationSeconds": 20}, {"id": "listen-short-04", "title": "Why some memories feel stronger", "transcript": "Lecturer: Today I want to distinguish feeling familiar with information from being able to retrieve it. Imagine that you have read a paragraph three times. On the third reading the wording may feel smooth and predictable. That experience can be reassuring, but it does not necessarily tell you whether you could explain the idea tomorrow without seeing the paragraph.\n\nLecturer: One alternative is to close the text and ask yourself a question. Trying to answer reveals what is available from memory and what needs another look. This does not mean that every attempt must succeed. An unsuccessful attempt can still identify a useful gap, provided that accurate feedback follows and the learner has an opportunity to correct the mistake.\n\nLecturer: Timing matters too. A question answered immediately after reading mainly tells us what is accessible at that moment. A similar question after a delay gives different evidence. It is particularly useful when the wording or example changes, because the learner has to recover the underlying idea rather than recognise a recently seen phrase.\n\nLecturer: Spacing practice is not the same as leaving a topic untouched until an examination. The intervals should be manageable. If a learner repeatedly cannot retrieve anything, the next step may be a clearer explanation or a shorter interval, rather than a more difficult test. A calendar can organise practice, but it cannot replace attention to the learner’s actual responses.\n\nLecturer: Finally, confidence is worth recording, though it is not a substitute for performance. A correct answer given with low confidence may deserve another check. A confident error also deserves attention, because the learner may not otherwise choose to revisit it. Taken together, answers, confidence and later recall give a more useful picture than any single immediate score. The point is to guide the next learning step, not to turn every practice question into a judgement of ability.", "segments": [{"speaker": "Lecturer", "text": "Today I want to distinguish feeling familiar with information from being able to retrieve it. Imagine that you have read a paragraph three times. On the third reading the wording may feel smooth and predictable. That experience can be reassuring, but it does not necessarily tell you whether you could explain the idea tomorrow without seeing the paragraph."}, {"speaker": "Lecturer", "text": "One alternative is to close the text and ask yourself a question. Trying to answer reveals what is available from memory and what needs another look. This does not mean that every attempt must succeed. An unsuccessful attempt can still identify a useful gap, provided that accurate feedback follows and the learner has an opportunity to correct the mistake."}, {"speaker": "Lecturer", "text": "Timing matters too. A question answered immediately after reading mainly tells us what is accessible at that moment. A similar question after a delay gives different evidence. It is particularly useful when the wording or example changes, because the learner has to recover the underlying idea rather than recognise a recently seen phrase."}, {"speaker": "Lecturer", "text": "Spacing practice is not the same as leaving a topic untouched until an examination. The intervals should be manageable. If a learner repeatedly cannot retrieve anything, the next step may be a clearer explanation or a shorter interval, rather than a more difficult test. A calendar can organise practice, but it cannot replace attention to the learner’s actual responses."}, {"speaker": "Lecturer", "text": "Finally, confidence is worth recording, though it is not a substitute for performance. A correct answer given with low confidence may deserve another check. A confident error also deserves attention, because the learner may not otherwise choose to revisit it. Taken together, answers, confidence and later recall give a more useful picture than any single immediate score. The point is to guide the next learning step, not to turn every practice question into a judgement of ability."}], "audio": "ielts-audio/listen-short-04.m4a", "questions": [{"id": "ls4-1", "type": "mcq", "prompt": "What does the lecturer say repeated reading can create?", "options": ["A feeling of familiarity without guaranteed later recall", "Permanent memory after three readings", "An inability to explain the main idea"], "answer": "A feeling of familiarity without guaranteed later recall", "explanation": "Smooth, predictable wording can feel familiar without demonstrating next-day recall.", "skill": "paraphrase and distractors"}, {"id": "ls4-2", "type": "completion", "prompt": "An unsuccessful retrieval attempt should be followed by accurate _____. Write ONE WORD.", "answer": "feedback", "maxWords": 1, "explanation": "Feedback and the opportunity to correct the mistake make the gap useful.", "skill": "detail and spelling"}, {"id": "ls4-3", "type": "mcq", "prompt": "Why change the example in a delayed question?", "options": ["To test the underlying idea rather than a familiar phrase", "To make the learner read faster", "To prevent all correct guessing"], "answer": "To test the underlying idea rather than a familiar phrase", "explanation": "Changed wording reduces simple recognition of a recently encountered phrase.", "skill": "paraphrase and distractors"}, {"id": "ls4-4", "type": "mcq", "prompt": "What might repeated inability to recall suggest doing next?", "options": ["Making every test harder", "Providing a clearer explanation or reducing the interval", "Waiting until the examination"], "answer": "Providing a clearer explanation or reducing the interval", "explanation": "The lecturer recommends a clearer explanation or a shorter interval when recall repeatedly fails.", "skill": "paraphrase and distractors"}, {"id": "ls4-5", "type": "completion", "prompt": "Alongside answers and later recall, record the learner’s _____. Write ONE WORD.", "answer": "confidence", "maxWords": 1, "explanation": "Confidence adds information but does not replace observed performance.", "skill": "detail and spelling"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 157.44, "audioLabel": "Prerecorded synthetic voice · Daniel (UK English)", "audioPreparationSeconds": 20}], "full": {"id": "listening-full-01", "title": "Listening · Four-part practice", "parts": [{"id": "listen-full-01", "title": "Part 1 · Booking a community course", "transcript": "Adviser: Good morning, Westbridge Community Centre. You are speaking to Daniel. How can I help?\n\nVisitor: Hello. I am looking for an evening course to do with a friend. Neither of us has tried pottery before, but we saw your photograph of people making bowls and thought it looked interesting.\n\nAdviser: That was probably the Saturday exhibition. We run two courses: an introduction to hand building, and a separate course using the pottery wheel. For complete beginners, I would suggest hand building. It gives you more time to learn how the clay behaves.\n\nVisitor: That sounds sensible. Is the course still on Tuesday evenings? We both work during the day, so anything before six would be difficult.\n\nAdviser: The autumn group met on Tuesdays. The new group meets on Thursdays, starting at six thirty. The sessions last two hours, and the caretaker keeps the building open for another fifteen minutes while everyone clears up.\n\nVisitor: Thursday is fine. When does the course begin? I have the fourteenth of November written down, although I may have copied the date of the exhibition by mistake.\n\nAdviser: Yes, that is the exhibition date. The course starts on the twenty-first of November. There are six sessions, with a week off in the middle because the centre is used for a local event. I can send you all the dates so there is no confusion.\n\nVisitor: Thank you. And what does it cost? We would need to know the total before booking, including anything we have to buy separately.\n\nAdviser: The course fee is eighty-four pounds per person. That covers teaching, clay and the firing of two finished pieces. If you make additional pieces, you can choose to pay for extra firing, but that is entirely optional. You do not need to buy a tool kit.\n\nVisitor: That is helpful. I assume we need old clothes. Is there anything particular that you recommend bringing?\n\nAdviser: An apron is the useful thing to bring. Some people wear gloves, but they can make it harder to feel the clay, so the tutor does not recommend them for most activities. We supply towels and have sinks beside every workbench.\n\nVisitor: My friend sometimes needs to leave promptly for a bus. Is there somewhere to leave work safely until the next lesson, or do we take everything home?\n\nAdviser: Unfinished work stays here. Each student has a tray on the drying shelves. Please write your name on the tray, rather than on the shelf. The shelves are moved between classes, and labels attached to the furniture can lead to mistakes.\n\nVisitor: Right, I will mention that. Could you explain where the pottery room is? I came to a concert at the centre years ago, but I do not remember seeing any studios.\n\nAdviser: The pottery room is in the annex, behind the main building. You enter through the main doors and follow the covered path across the courtyard. There is a ramp all the way to the annex, and the room itself is on the ground floor.\n\nVisitor: We will probably come by bicycle. Is it all right to lock bicycles to the fence near the courtyard?\n\nAdviser: Please use the racks beside the library instead. The fence has to remain clear for deliveries. The library is next door, on the left as you face our main entrance, and the racks are well lit in the evening.\n\nVisitor: Fine. What is the minimum number of people for the course to run? We once booked a language class that was cancelled at the last minute.\n\nAdviser: We need eight bookings. We currently have seven, so if both of you join, the course can go ahead. The maximum group size is twelve, which gives the tutor enough time to help each student individually.\n\nVisitor: That is reassuring. How do we secure the places? Can I reserve them today and pay when we arrive?\n\nAdviser: I can hold two places until tomorrow evening. Payment is due by Friday. You can pay through the booking page or at reception, but not to the tutor during class. Once payment arrives, we email the joining instructions and a receipt.\n\nVisitor: I will contact my friend now. If either of us has a question about accessibility or the materials, whom should we ask?\n\nAdviser: Email the course coordinator, whose surname is Mercer. That is M, E, R, C, E, R. Her contact details are on the booking page. She can check anything specific with the tutor before you decide.", "segments": [{"speaker": "Adviser", "text": "Good morning, Westbridge Community Centre. You are speaking to Daniel. How can I help?"}, {"speaker": "Visitor", "text": "Hello. I am looking for an evening course to do with a friend. Neither of us has tried pottery before, but we saw your photograph of people making bowls and thought it looked interesting."}, {"speaker": "Adviser", "text": "That was probably the Saturday exhibition. We run two courses: an introduction to hand building, and a separate course using the pottery wheel. For complete beginners, I would suggest hand building. It gives you more time to learn how the clay behaves."}, {"speaker": "Visitor", "text": "That sounds sensible. Is the course still on Tuesday evenings? We both work during the day, so anything before six would be difficult."}, {"speaker": "Adviser", "text": "The autumn group met on Tuesdays. The new group meets on Thursdays, starting at six thirty. The sessions last two hours, and the caretaker keeps the building open for another fifteen minutes while everyone clears up."}, {"speaker": "Visitor", "text": "Thursday is fine. When does the course begin? I have the fourteenth of November written down, although I may have copied the date of the exhibition by mistake."}, {"speaker": "Adviser", "text": "Yes, that is the exhibition date. The course starts on the twenty-first of November. There are six sessions, with a week off in the middle because the centre is used for a local event. I can send you all the dates so there is no confusion."}, {"speaker": "Visitor", "text": "Thank you. And what does it cost? We would need to know the total before booking, including anything we have to buy separately."}, {"speaker": "Adviser", "text": "The course fee is eighty-four pounds per person. That covers teaching, clay and the firing of two finished pieces. If you make additional pieces, you can choose to pay for extra firing, but that is entirely optional. You do not need to buy a tool kit."}, {"speaker": "Visitor", "text": "That is helpful. I assume we need old clothes. Is there anything particular that you recommend bringing?"}, {"speaker": "Adviser", "text": "An apron is the useful thing to bring. Some people wear gloves, but they can make it harder to feel the clay, so the tutor does not recommend them for most activities. We supply towels and have sinks beside every workbench."}, {"speaker": "Visitor", "text": "My friend sometimes needs to leave promptly for a bus. Is there somewhere to leave work safely until the next lesson, or do we take everything home?"}, {"speaker": "Adviser", "text": "Unfinished work stays here. Each student has a tray on the drying shelves. Please write your name on the tray, rather than on the shelf. The shelves are moved between classes, and labels attached to the furniture can lead to mistakes."}, {"speaker": "Visitor", "text": "Right, I will mention that. Could you explain where the pottery room is? I came to a concert at the centre years ago, but I do not remember seeing any studios."}, {"speaker": "Adviser", "text": "The pottery room is in the annex, behind the main building. You enter through the main doors and follow the covered path across the courtyard. There is a ramp all the way to the annex, and the room itself is on the ground floor."}, {"speaker": "Visitor", "text": "We will probably come by bicycle. Is it all right to lock bicycles to the fence near the courtyard?"}, {"speaker": "Adviser", "text": "Please use the racks beside the library instead. The fence has to remain clear for deliveries. The library is next door, on the left as you face our main entrance, and the racks are well lit in the evening."}, {"speaker": "Visitor", "text": "Fine. What is the minimum number of people for the course to run? We once booked a language class that was cancelled at the last minute."}, {"speaker": "Adviser", "text": "We need eight bookings. We currently have seven, so if both of you join, the course can go ahead. The maximum group size is twelve, which gives the tutor enough time to help each student individually."}, {"speaker": "Visitor", "text": "That is reassuring. How do we secure the places? Can I reserve them today and pay when we arrive?"}, {"speaker": "Adviser", "text": "I can hold two places until tomorrow evening. Payment is due by Friday. You can pay through the booking page or at reception, but not to the tutor during class. Once payment arrives, we email the joining instructions and a receipt."}, {"speaker": "Visitor", "text": "I will contact my friend now. If either of us has a question about accessibility or the materials, whom should we ask?"}, {"speaker": "Adviser", "text": "Email the course coordinator, whose surname is Mercer. That is M, E, R, C, E, R. Her contact details are on the booking page. She can check anything specific with the tutor before you decide."}], "audio": "ielts-audio/listen-full-01.m4a", "questions": [{"id": "lf1-1", "type": "completion", "prompt": "Course day: _____. Write ONE WORD.", "answer": "Thursday", "maxWords": 1, "explanation": "Tuesday was the previous group; the new group meets on Thursdays.", "skill": "detail and spelling", "acceptedAnswers": ["Thursday", "Thursdays"]}, {"id": "lf1-2", "type": "completion", "prompt": "Start date: _____ November. Write ONE WORD OR A NUMBER.", "answer": "21", "maxWords": 1, "explanation": "The fourteenth is the exhibition; the course begins on the twenty-first.", "skill": "detail and spelling", "acceptedAnswers": ["21", "twenty-first"]}, {"id": "lf1-3", "type": "completion", "prompt": "Course fee per person: £_____. Write A NUMBER.", "answer": "84", "maxWords": 1, "explanation": "Eighty-four pounds includes teaching, clay and firing two pieces.", "skill": "detail and spelling", "acceptedAnswers": ["84", "eighty-four"]}, {"id": "lf1-4", "type": "completion", "prompt": "Recommended item to bring: an _____. Write ONE WORD.", "answer": "apron", "maxWords": 1, "explanation": "The adviser recommends an apron, not gloves or a tool kit.", "skill": "detail and spelling"}, {"id": "lf1-5", "type": "completion", "prompt": "Write your name on your _____. Write ONE WORD.", "answer": "tray", "maxWords": 1, "explanation": "The tray must be labelled because the shelves move between classes.", "skill": "detail and spelling"}, {"id": "lf1-6", "type": "completion", "prompt": "The pottery room is in the _____. Write ONE WORD.", "answer": "annex", "maxWords": 1, "explanation": "The annex is behind the main building.", "skill": "detail and spelling"}, {"id": "lf1-7", "type": "completion", "prompt": "Bicycle racks are beside the _____. Write ONE WORD.", "answer": "library", "maxWords": 1, "explanation": "Bicycles should use the library racks, not the delivery fence.", "skill": "detail and spelling"}, {"id": "lf1-8", "type": "completion", "prompt": "Minimum number of bookings: _____. Write ONE WORD OR A NUMBER.", "answer": "8", "maxWords": 1, "explanation": "Eight are needed; seven are currently booked and twelve is the maximum.", "skill": "detail and spelling", "acceptedAnswers": ["8", "eight"]}, {"id": "lf1-9", "type": "completion", "prompt": "Payment deadline: _____. Write ONE WORD.", "answer": "Friday", "maxWords": 1, "explanation": "Places are temporarily held, but payment is due by Friday.", "skill": "detail and spelling"}, {"id": "lf1-10", "type": "completion", "prompt": "Coordinator’s surname: _____. Write ONE WORD.", "answer": "Mercer", "maxWords": 1, "explanation": "The adviser spells M-E-R-C-E-R.", "skill": "detail and spelling"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 396.33, "audioLabel": "Prerecorded synthetic voices · Daniel (UK English) and Samantha (US English)", "audioPreparationSeconds": 45, "audioMidpointPreparationSeconds": 45, "audioFinalCheckSeconds": 15}, {"id": "listen-full-02", "title": "Part 2 · Volunteering at a community garden", "transcript": "Guide: Welcome to Green Lane Garden. I am your volunteer coordinator, and I will explain how the site works before you choose an activity. The garden opened five years ago on land that had been empty for a decade. Some people remember it as a car park, but before it became empty it was a small railway goods yard. We have kept a short section of track beside the gate as a reminder. Nothing here is a reconstruction of an old farm; this is a working community space with a history of its own.\n\nGuide: The main aim is to give local residents somewhere to learn and work together. We do sell some produce to help with running costs, but maximising sales is not our priority. Nor do you need a private garden to take part. People who live in flats often find the shared growing areas particularly useful. What matters is willingness to cooperate, including with people whose experience and ideas differ from yours.\n\nGuide: Today we have changed the meeting point for the afternoon group. Normally they gather at the greenhouse. A delivery will block that path until two o’clock, so everyone should meet at the covered bench instead. It is just beyond the main gate. The shed will be open for tools, but please do not wait there, because the tool team needs room to move equipment safely.\n\nGuide: Before starting a task, sign in using the paper sheet on the noticeboard. We experimented with a phone application last year, but some volunteers did not carry phones, and the signal was unreliable. Paper is therefore our standard method for everyone. If you leave early, record the time beside your name. This is not about comparing how hard people work; it tells us who is still on site in an emergency.\n\nGuide: The morning break is flexible. There is a suggested time on the board, but teams may finish a short task before stopping. Please use the kitchen for drinking water rather than the outdoor tap by the compost area. That tap is supplied from rainwater tanks. The tanks are useful for plants, but the water has not been treated for drinking. Cups are available in the kitchen if you have not brought a bottle.\n\nGuide: Now I will describe five jobs for the coming week. You can put your name beside one or more, and the team leader will confirm a suitable time. You are not committing to do the same job every week. We encourage people to try different activities, and we make adjustments when somebody needs a seated task or a shorter session.\n\nGuide: First, the seed team needs help preparing packets for the spring exchange. The seeds have already been dried and sorted. Your task will be to write labels showing the variety and collection date, then attach them to the packets. Accuracy is more important than speed, because an incorrect label can confuse gardeners months later. The team has a clear list to copy, so you will not need to identify seeds by sight.\n\nGuide: Second, we are repairing the raised beds nearest the wall. The timber has been cut to size, and the heavier pieces will be moved by trained volunteers. Others can help by checking the screws once the frames are assembled. A loose screw is easier to fix before soil is added. The coordinator will show you the check before you begin, and all tools must go back to the marked tray.\n\nGuide: Third, the wildlife group is running an insect count. We will divide the garden into small areas and observe each for the same length of time. Please bring a notebook if you have one, although spare sheets are available. You will record sightings rather than collect insects. A simple identification guide will help distinguish the groups we are counting; anything uncertain can be photographed for a later check.\n\nGuide: Fourth, the compost team will turn the older pile on Wednesday. Wear boots, because the ground beside it can be slippery even when the main paths are dry. Gloves are supplied. New volunteers will work alongside someone experienced, and there is no need to lift a heavy load in one go. Small amounts are easier to handle and work just as well.\n\nGuide: Finally, we need two people to prepare the display for our open day. The photographs are already printed. Please arrange them by season, starting with spring, so visitors can see how the garden changes through the year. Do not arrange them by the date the photographer sent them in: several winter photographs arrived very recently. We will add short captions together after the order has been checked.", "segments": [{"speaker": "Guide", "text": "Welcome to Green Lane Garden. I am your volunteer coordinator, and I will explain how the site works before you choose an activity. The garden opened five years ago on land that had been empty for a decade. Some people remember it as a car park, but before it became empty it was a small railway goods yard. We have kept a short section of track beside the gate as a reminder. Nothing here is a reconstruction of an old farm; this is a working community space with a history of its own."}, {"speaker": "Guide", "text": "The main aim is to give local residents somewhere to learn and work together. We do sell some produce to help with running costs, but maximising sales is not our priority. Nor do you need a private garden to take part. People who live in flats often find the shared growing areas particularly useful. What matters is willingness to cooperate, including with people whose experience and ideas differ from yours."}, {"speaker": "Guide", "text": "Today we have changed the meeting point for the afternoon group. Normally they gather at the greenhouse. A delivery will block that path until two o’clock, so everyone should meet at the covered bench instead. It is just beyond the main gate. The shed will be open for tools, but please do not wait there, because the tool team needs room to move equipment safely."}, {"speaker": "Guide", "text": "Before starting a task, sign in using the paper sheet on the noticeboard. We experimented with a phone application last year, but some volunteers did not carry phones, and the signal was unreliable. Paper is therefore our standard method for everyone. If you leave early, record the time beside your name. This is not about comparing how hard people work; it tells us who is still on site in an emergency."}, {"speaker": "Guide", "text": "The morning break is flexible. There is a suggested time on the board, but teams may finish a short task before stopping. Please use the kitchen for drinking water rather than the outdoor tap by the compost area. That tap is supplied from rainwater tanks. The tanks are useful for plants, but the water has not been treated for drinking. Cups are available in the kitchen if you have not brought a bottle."}, {"speaker": "Guide", "text": "Now I will describe five jobs for the coming week. You can put your name beside one or more, and the team leader will confirm a suitable time. You are not committing to do the same job every week. We encourage people to try different activities, and we make adjustments when somebody needs a seated task or a shorter session."}, {"speaker": "Guide", "text": "First, the seed team needs help preparing packets for the spring exchange. The seeds have already been dried and sorted. Your task will be to write labels showing the variety and collection date, then attach them to the packets. Accuracy is more important than speed, because an incorrect label can confuse gardeners months later. The team has a clear list to copy, so you will not need to identify seeds by sight."}, {"speaker": "Guide", "text": "Second, we are repairing the raised beds nearest the wall. The timber has been cut to size, and the heavier pieces will be moved by trained volunteers. Others can help by checking the screws once the frames are assembled. A loose screw is easier to fix before soil is added. The coordinator will show you the check before you begin, and all tools must go back to the marked tray."}, {"speaker": "Guide", "text": "Third, the wildlife group is running an insect count. We will divide the garden into small areas and observe each for the same length of time. Please bring a notebook if you have one, although spare sheets are available. You will record sightings rather than collect insects. A simple identification guide will help distinguish the groups we are counting; anything uncertain can be photographed for a later check."}, {"speaker": "Guide", "text": "Fourth, the compost team will turn the older pile on Wednesday. Wear boots, because the ground beside it can be slippery even when the main paths are dry. Gloves are supplied. New volunteers will work alongside someone experienced, and there is no need to lift a heavy load in one go. Small amounts are easier to handle and work just as well."}, {"speaker": "Guide", "text": "Finally, we need two people to prepare the display for our open day. The photographs are already printed. Please arrange them by season, starting with spring, so visitors can see how the garden changes through the year. Do not arrange them by the date the photographer sent them in: several winter photographs arrived very recently. We will add short captions together after the order has been checked."}], "audio": "ielts-audio/listen-full-02.m4a", "questions": [{"id": "lf2-1", "type": "mcq", "prompt": "What occupied the site before it became empty?", "options": ["A railway goods yard", "A car park", "An old farm"], "answer": "A railway goods yard", "explanation": "The speaker corrects a common memory of the site as a car park.", "skill": "paraphrase and distractors"}, {"id": "lf2-2", "type": "mcq", "prompt": "What is the garden’s main aim?", "options": ["To maximise vegetable sales", "To provide shared learning and work", "To help residents buy private gardens"], "answer": "To provide shared learning and work", "explanation": "Sales help with costs, but learning and working together is the priority.", "skill": "paraphrase and distractors"}, {"id": "lf2-3", "type": "mcq", "prompt": "Where should the afternoon group meet today?", "options": ["At the greenhouse", "At the tool shed", "At the covered bench"], "answer": "At the covered bench", "explanation": "A delivery blocks the usual greenhouse meeting point.", "skill": "paraphrase and distractors"}, {"id": "lf2-4", "type": "mcq", "prompt": "Why is the sign-in sheet used?", "options": ["To identify who is on site", "To rank volunteers by working time", "To decide which volunteers can use phones"], "answer": "To identify who is on site", "explanation": "The record identifies who remains on site in an emergency.", "skill": "paraphrase and distractors"}, {"id": "lf2-5", "type": "mcq", "prompt": "Why should volunteers avoid drinking from the outdoor tap?", "options": ["Its water is untreated rainwater", "The tap is broken", "Its water is reserved for the kitchen"], "answer": "Its water is untreated rainwater", "explanation": "The outdoor tap draws untreated water from rainwater tanks.", "skill": "paraphrase and distractors"}, {"id": "lf2-6", "type": "completion", "prompt": "Seed preparation: write _____ for the packets. Write ONE WORD.", "answer": "labels", "maxWords": 1, "explanation": "The seeds have been prepared; the task is accurate labels.", "skill": "detail and spelling"}, {"id": "lf2-7", "type": "completion", "prompt": "Raised beds: check the _____ after assembly. Write ONE WORD.", "answer": "screws", "maxWords": 1, "explanation": "Checking screws before adding soil makes repairs easier.", "skill": "detail and spelling"}, {"id": "lf2-8", "type": "completion", "prompt": "Insect count: bring a _____ if possible. Write ONE WORD.", "answer": "notebook", "maxWords": 1, "explanation": "A notebook is useful for recording sightings; spare sheets exist.", "skill": "detail and spelling"}, {"id": "lf2-9", "type": "completion", "prompt": "Compost work: wear _____. Write ONE WORD.", "answer": "boots", "maxWords": 1, "explanation": "Boots are needed because the ground can be slippery.", "skill": "detail and spelling"}, {"id": "lf2-10", "type": "completion", "prompt": "Photograph display: arrange the pictures by _____. Write ONE WORD.", "answer": "season", "maxWords": 1, "explanation": "The display should show seasonal changes, not submission dates.", "skill": "detail and spelling"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 416.27, "audioLabel": "Prerecorded synthetic voice · Daniel (UK English)", "audioPreparationSeconds": 45, "audioMidpointPreparationSeconds": 45, "audioFinalCheckSeconds": 15}, {"id": "listen-full-03", "title": "Part 3 · Investigating study spaces", "transcript": "Maya: Shall we review the tutor’s comments on our proposal? We originally wanted to compare examination results for students using different study spaces, but she thought that would be too ambitious for a six-week project.\n\nLeo: Yes, and examination results depend on so many other things. She suggested focusing on how students choose a study space instead. That gives us a clear question we can explore without claiming that a particular room causes better grades.\n\nMaya: I liked that suggestion. I had assumed that silence would be everyone’s main concern, but the preliminary interviews were more varied. One student cared most about finding a plug socket; another wanted to sit near friends, even though they were studying different subjects.\n\nLeo: And several students said their preference changed depending on the task. They wanted a quiet room for difficult reading, but a shared table when checking answers with classmates. So the important insight was that preferences were not fixed for each person.\n\nMaya: We need to decide where to recruit participants. An invitation in the library would be convenient, but it could miss students who prefer studying elsewhere. The tutor suggested using messages sent through course representatives across several departments.\n\nLeo: That seems better. We should still say clearly that students who rarely use the library can take part. Otherwise the title of the project might make them think it is not relevant. We are not aiming for a perfectly representative national sample, but we can avoid an obvious local bias.\n\nMaya: What about the diary method? Asking people to describe their entire study day would produce a lot of writing. I think some would stop after a couple of days, especially if they were busy.\n\nLeo: Agreed. Let us ask for a short entry immediately after each study session: location, type of task and reason for choosing the space. That should be easier to remember accurately than reconstructing the whole day at bedtime. We can keep the optional comments very brief.\n\nMaya: One tutor comment puzzled me at first. She said we should record whether a student had a realistic alternative available. Why does that matter if we already ask why they chose the room?\n\nLeo: Because choosing a space does not necessarily mean preferring it. If the quiet room is full, someone may use the café despite finding it noisy. Recording alternatives helps us distinguish a preference from a decision made because there was no other practical option.\n\nMaya: That makes sense. We should mention it in the explanation before the diary begins. The participants do not need to name every room they considered, just tell us whether their first choice was available. It is a small addition, but it changes how we interpret the location data.\n\nLeo: We also need a plan for incomplete diaries. I initially thought we should remove anyone who missed an entry, but that could leave us with very few participants. It might also favour students with more predictable routines.\n\nMaya: The tutor suggested keeping completed entries and reporting how much data is missing. We must not fill the gaps by assuming students stayed in the same place. We can ask once whether they want to add a missing entry, but they should not feel pressured to invent details.\n\nLeo: Good. Let us divide up the remaining work. We have four tasks, and we should make it clear who leads each one so that we do not accidentally duplicate things.\n\nMaya: I can revise the participant instructions. I wrote the first version, and I have the tutor’s comments beside it. I will send you the revised wording before it goes out, but I will take responsibility for completing that task.\n\nLeo: Fine. I will lead the online diary form. I have used the survey software before, so setting up the fields should be straightforward. You can test it on your phone, but I will fix any problems with the layout or export.\n\nMaya: For the coding guide, we should work together. If we each interpret a reason differently, our categories will not mean much. Let us both code the first five sample entries, compare our decisions, and then agree the definitions.\n\nLeo: Yes, that needs both of us. And I can draft the recruitment message after finishing the form. It needs to explain that library use is not a requirement and that participation is voluntary. You can read it before I send it, but I will prepare the draft.\n\nMaya: That leaves the timetable. We should run a small pilot before recruiting the main group, then revise anything confusing. If the form works well, there is no reason to add more questions just because we still have space on the screen.", "segments": [{"speaker": "Maya", "text": "Shall we review the tutor’s comments on our proposal? We originally wanted to compare examination results for students using different study spaces, but she thought that would be too ambitious for a six-week project."}, {"speaker": "Leo", "text": "Yes, and examination results depend on so many other things. She suggested focusing on how students choose a study space instead. That gives us a clear question we can explore without claiming that a particular room causes better grades."}, {"speaker": "Maya", "text": "I liked that suggestion. I had assumed that silence would be everyone’s main concern, but the preliminary interviews were more varied. One student cared most about finding a plug socket; another wanted to sit near friends, even though they were studying different subjects."}, {"speaker": "Leo", "text": "And several students said their preference changed depending on the task. They wanted a quiet room for difficult reading, but a shared table when checking answers with classmates. So the important insight was that preferences were not fixed for each person."}, {"speaker": "Maya", "text": "We need to decide where to recruit participants. An invitation in the library would be convenient, but it could miss students who prefer studying elsewhere. The tutor suggested using messages sent through course representatives across several departments."}, {"speaker": "Leo", "text": "That seems better. We should still say clearly that students who rarely use the library can take part. Otherwise the title of the project might make them think it is not relevant. We are not aiming for a perfectly representative national sample, but we can avoid an obvious local bias."}, {"speaker": "Maya", "text": "What about the diary method? Asking people to describe their entire study day would produce a lot of writing. I think some would stop after a couple of days, especially if they were busy."}, {"speaker": "Leo", "text": "Agreed. Let us ask for a short entry immediately after each study session: location, type of task and reason for choosing the space. That should be easier to remember accurately than reconstructing the whole day at bedtime. We can keep the optional comments very brief."}, {"speaker": "Maya", "text": "One tutor comment puzzled me at first. She said we should record whether a student had a realistic alternative available. Why does that matter if we already ask why they chose the room?"}, {"speaker": "Leo", "text": "Because choosing a space does not necessarily mean preferring it. If the quiet room is full, someone may use the café despite finding it noisy. Recording alternatives helps us distinguish a preference from a decision made because there was no other practical option."}, {"speaker": "Maya", "text": "That makes sense. We should mention it in the explanation before the diary begins. The participants do not need to name every room they considered, just tell us whether their first choice was available. It is a small addition, but it changes how we interpret the location data."}, {"speaker": "Leo", "text": "We also need a plan for incomplete diaries. I initially thought we should remove anyone who missed an entry, but that could leave us with very few participants. It might also favour students with more predictable routines."}, {"speaker": "Maya", "text": "The tutor suggested keeping completed entries and reporting how much data is missing. We must not fill the gaps by assuming students stayed in the same place. We can ask once whether they want to add a missing entry, but they should not feel pressured to invent details."}, {"speaker": "Leo", "text": "Good. Let us divide up the remaining work. We have four tasks, and we should make it clear who leads each one so that we do not accidentally duplicate things."}, {"speaker": "Maya", "text": "I can revise the participant instructions. I wrote the first version, and I have the tutor’s comments beside it. I will send you the revised wording before it goes out, but I will take responsibility for completing that task."}, {"speaker": "Leo", "text": "Fine. I will lead the online diary form. I have used the survey software before, so setting up the fields should be straightforward. You can test it on your phone, but I will fix any problems with the layout or export."}, {"speaker": "Maya", "text": "For the coding guide, we should work together. If we each interpret a reason differently, our categories will not mean much. Let us both code the first five sample entries, compare our decisions, and then agree the definitions."}, {"speaker": "Leo", "text": "Yes, that needs both of us. And I can draft the recruitment message after finishing the form. It needs to explain that library use is not a requirement and that participation is voluntary. You can read it before I send it, but I will prepare the draft."}, {"speaker": "Maya", "text": "That leaves the timetable. We should run a small pilot before recruiting the main group, then revise anything confusing. If the form works well, there is no reason to add more questions just because we still have space on the screen."}], "audio": "ielts-audio/listen-full-03.m4a", "questions": [{"id": "lf3-1", "type": "mcq", "prompt": "What is the revised project focus?", "options": ["How students choose study spaces", "Whether libraries improve examination grades", "Which department has the highest results"], "answer": "How students choose study spaces", "explanation": "The tutor narrows the project to choices, avoiding unsupported causal claims about grades.", "skill": "paraphrase and distractors"}, {"id": "lf3-2", "type": "mcq", "prompt": "What did the preliminary interviews reveal?", "options": ["Every student preferred silence", "Preferences could change with the task", "Plug sockets mattered only to library users"], "answer": "Preferences could change with the task", "explanation": "The same person may prefer different spaces for difficult reading and shared answer checking.", "skill": "paraphrase and distractors"}, {"id": "lf3-3", "type": "mcq", "prompt": "Why recruit through several departments?", "options": ["To include students who study outside the library", "To restrict participation to course representatives", "To obtain a national sample"], "answer": "To include students who study outside the library", "explanation": "Library-only recruitment could miss students who prefer other spaces.", "skill": "paraphrase and distractors"}, {"id": "lf3-4", "type": "mcq", "prompt": "Why make diary entries immediately after each session?", "options": ["To avoid having to recall a whole day later", "To make students study more often", "To obtain longer written responses"], "answer": "To avoid having to recall a whole day later", "explanation": "Short immediate entries reduce the memory demands of reconstructing an entire day.", "skill": "paraphrase and distractors"}, {"id": "lf3-5", "type": "mcq", "prompt": "Why record whether alternative spaces were available?", "options": ["A chosen space may not have been the preferred one", "Students may not know the room names", "Every participant must compare all rooms"], "answer": "A chosen space may not have been the preferred one", "explanation": "A full quiet room can force someone to use a café despite preferring silence.", "skill": "paraphrase and distractors"}, {"id": "lf3-6", "type": "mcq", "prompt": "How will they handle incomplete diaries?", "options": ["Remove every participant who misses an entry", "Keep completed entries and report missing data", "Fill gaps using the previous recorded location"], "answer": "Keep completed entries and report missing data", "explanation": "They will retain evidence and disclose missingness rather than invent entries.", "skill": "paraphrase and distractors"}, {"id": "lf3-7", "type": "matching", "prompt": "Who will lead the revision of participant instructions?", "options": ["Maya", "Leo", "Both students"], "answer": "Maya", "explanation": "Maya takes responsibility for finishing the revised instructions.", "skill": "speaker responsibility"}, {"id": "lf3-8", "type": "matching", "prompt": "Who will lead the online diary form?", "options": ["Maya", "Leo", "Both students"], "answer": "Leo", "explanation": "Leo will set up the form and fix layout or export problems.", "skill": "speaker responsibility"}, {"id": "lf3-9", "type": "matching", "prompt": "Who will develop the coding guide?", "options": ["Maya", "Leo", "Both students"], "answer": "Both students", "explanation": "They will both code sample entries and agree category definitions.", "skill": "speaker responsibility"}, {"id": "lf3-10", "type": "matching", "prompt": "Who will draft the recruitment message?", "options": ["Maya", "Leo", "Both students"], "answer": "Leo", "explanation": "Leo volunteers to draft the message; Maya will review it.", "skill": "speaker responsibility"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 418.64, "audioLabel": "Prerecorded synthetic voices · Daniel (UK English) and Samantha (US English)", "audioPreparationSeconds": 45, "audioMidpointPreparationSeconds": 45, "audioFinalCheckSeconds": 15}, {"id": "listen-full-04", "title": "Part 4 · Measuring urban heat", "transcript": "Lecturer: Today we will consider how researchers investigate heat in cities. A familiar photograph shows a thermal image of a street, with warm surfaces coloured red and cooler ones blue. Such images are useful, but we need to be precise about what they represent. A camera looking down from above measures surface temperature. That is not the same measurement as the air temperature reported in a weather forecast, and neither measurement alone fully describes what a pedestrian experiences.\n\nLecturer: Think about a person waiting at a bus stop. The air may be warm, but direct sunlight can make the person feel much hotter. Nearby walls and road surfaces also exchange heat with the surroundings. Shade can therefore improve comfort even when the measured air temperature changes very little. This is one reason why a shaded footpath may feel noticeably different from an exposed one a few metres away.\n\nLecturer: Vegetation can affect local conditions in more than one way. A tree intercepts sunlight, creating shade, and water can also evaporate from its leaves. In that second process, energy is used to change liquid water into water vapour. However, the effect depends partly on whether the tree has enough water available. Simply counting trees without considering their condition may tell us less than we expect about their cooling contribution.\n\nLecturer: Researchers comparing different streets must make measurements that are genuinely comparable. For air measurements near people, one basic requirement is to place sensors at the same height. A sensor just above a hot road surface may give a different result from one positioned beside a person’s head. The sensor also needs suitable protection from direct solar radiation; otherwise the instrument itself can become warmer than the air it is supposed to measure.\n\nLecturer: Time is another consideration. If one street is measured early in the morning and another at midday, the difference may reflect the time of day rather than the street design. A strong comparison therefore takes measurements simultaneously where possible. If only one portable instrument is available, researchers should acknowledge the limitation and design repeated visits carefully, rather than treating a single walk as a definitive ranking of streets.\n\nLecturer: Now let us examine a fictional student investigation. The students compared two walking routes between a station and a college. One route passed under mature trees; the other followed an open commercial street. They recorded temperature on several afternoons and asked volunteers to rate their comfort. Importantly, they also recorded wind speed, because moving air could affect comfort independently of the shade. It would be misleading to attribute every reported difference to the trees.\n\nLecturer: The volunteers wore small sensors, but the students did not rely on instruments alone. After each walk, volunteers completed a brief questionnaire. It asked how warm they felt and whether they would choose the route again. Those are distinct questions: a person might dislike the heat but still prefer a shorter journey. Recording both makes the findings more informative than treating route choice as a direct measure of thermal comfort.\n\nLecturer: The investigation had a limitation. All volunteers were students from the same college, so the sample did not include many older adults. Older people may have different mobility needs and may experience heat differently. The students therefore could describe the responses of their volunteers, but they could not assume that the same pattern applied equally to every resident. A larger sample would help only if recruitment also reached a wider range of people.\n\nLecturer: For city planners, these details affect decisions. A new tree may take years to provide substantial shade, and some streets have underground services that restrict planting. Temporary structures can sometimes provide shade sooner. Whatever the solution, planners should pay particular attention to bus stops, where people may need to stand in one place rather than choose a cooler route. Seating and access also matter, especially for people who cannot comfortably walk farther.\n\nLecturer: Finally, an intervention should be evaluated after it is installed. One hot afternoon is not enough to establish a reliable effect. Repeated measurements should cover different weather conditions, using comparable methods before and after the change. The aim is not to produce a single impressive temperature reduction for a publicity poster. It is to understand when the intervention helps, whom it helps, and what limitations remain, so that the next decision is better informed.", "segments": [{"speaker": "Lecturer", "text": "Today we will consider how researchers investigate heat in cities. A familiar photograph shows a thermal image of a street, with warm surfaces coloured red and cooler ones blue. Such images are useful, but we need to be precise about what they represent. A camera looking down from above measures surface temperature. That is not the same measurement as the air temperature reported in a weather forecast, and neither measurement alone fully describes what a pedestrian experiences."}, {"speaker": "Lecturer", "text": "Think about a person waiting at a bus stop. The air may be warm, but direct sunlight can make the person feel much hotter. Nearby walls and road surfaces also exchange heat with the surroundings. Shade can therefore improve comfort even when the measured air temperature changes very little. This is one reason why a shaded footpath may feel noticeably different from an exposed one a few metres away."}, {"speaker": "Lecturer", "text": "Vegetation can affect local conditions in more than one way. A tree intercepts sunlight, creating shade, and water can also evaporate from its leaves. In that second process, energy is used to change liquid water into water vapour. However, the effect depends partly on whether the tree has enough water available. Simply counting trees without considering their condition may tell us less than we expect about their cooling contribution."}, {"speaker": "Lecturer", "text": "Researchers comparing different streets must make measurements that are genuinely comparable. For air measurements near people, one basic requirement is to place sensors at the same height. A sensor just above a hot road surface may give a different result from one positioned beside a person’s head. The sensor also needs suitable protection from direct solar radiation; otherwise the instrument itself can become warmer than the air it is supposed to measure."}, {"speaker": "Lecturer", "text": "Time is another consideration. If one street is measured early in the morning and another at midday, the difference may reflect the time of day rather than the street design. A strong comparison therefore takes measurements simultaneously where possible. If only one portable instrument is available, researchers should acknowledge the limitation and design repeated visits carefully, rather than treating a single walk as a definitive ranking of streets."}, {"speaker": "Lecturer", "text": "Now let us examine a fictional student investigation. The students compared two walking routes between a station and a college. One route passed under mature trees; the other followed an open commercial street. They recorded temperature on several afternoons and asked volunteers to rate their comfort. Importantly, they also recorded wind speed, because moving air could affect comfort independently of the shade. It would be misleading to attribute every reported difference to the trees."}, {"speaker": "Lecturer", "text": "The volunteers wore small sensors, but the students did not rely on instruments alone. After each walk, volunteers completed a brief questionnaire. It asked how warm they felt and whether they would choose the route again. Those are distinct questions: a person might dislike the heat but still prefer a shorter journey. Recording both makes the findings more informative than treating route choice as a direct measure of thermal comfort."}, {"speaker": "Lecturer", "text": "The investigation had a limitation. All volunteers were students from the same college, so the sample did not include many older adults. Older people may have different mobility needs and may experience heat differently. The students therefore could describe the responses of their volunteers, but they could not assume that the same pattern applied equally to every resident. A larger sample would help only if recruitment also reached a wider range of people."}, {"speaker": "Lecturer", "text": "For city planners, these details affect decisions. A new tree may take years to provide substantial shade, and some streets have underground services that restrict planting. Temporary structures can sometimes provide shade sooner. Whatever the solution, planners should pay particular attention to bus stops, where people may need to stand in one place rather than choose a cooler route. Seating and access also matter, especially for people who cannot comfortably walk farther."}, {"speaker": "Lecturer", "text": "Finally, an intervention should be evaluated after it is installed. One hot afternoon is not enough to establish a reliable effect. Repeated measurements should cover different weather conditions, using comparable methods before and after the change. The aim is not to produce a single impressive temperature reduction for a publicity poster. It is to understand when the intervention helps, whom it helps, and what limitations remain, so that the next decision is better informed."}], "audio": "ielts-audio/listen-full-04.m4a", "questions": [{"id": "lf4-1", "type": "completion", "prompt": "A thermal camera looking down records _____ temperature. Write ONE WORD.", "answer": "surface", "maxWords": 1, "explanation": "A thermal image measures surfaces; the lecturer distinguishes this from air temperature.", "skill": "detail and spelling"}, {"id": "lf4-2", "type": "completion", "prompt": "Even with little change in air temperature, _____ can improve comfort. Write ONE WORD.", "answer": "shade", "maxWords": 1, "explanation": "Shade reduces direct solar exposure and can improve comfort without a large air-temperature change.", "skill": "detail and spelling"}, {"id": "lf4-3", "type": "completion", "prompt": "Cooling through evaporation depends partly on available _____. Write ONE WORD.", "answer": "water", "maxWords": 1, "explanation": "Leaf evaporation requires water; tree condition and water availability matter.", "skill": "detail and spelling"}, {"id": "lf4-4", "type": "completion", "prompt": "Comparable air measurements require sensors at the same _____. Write ONE WORD.", "answer": "height", "maxWords": 1, "explanation": "Different heights above a hot road can give different readings.", "skill": "detail and spelling"}, {"id": "lf4-5", "type": "completion", "prompt": "Where possible, measurements in different streets should be taken _____. Write ONE WORD.", "answer": "simultaneously", "maxWords": 1, "explanation": "Measuring at the same time helps avoid confounding street differences with time of day.", "skill": "detail and spelling"}, {"id": "lf4-6", "type": "completion", "prompt": "The students also recorded _____ because it could affect comfort. Write NO MORE THAN TWO WORDS.", "answer": "wind speed", "maxWords": 2, "explanation": "Moving air may change comfort independently of shade.", "skill": "detail and spelling"}, {"id": "lf4-7", "type": "completion", "prompt": "After each walk, volunteers completed a brief _____. Write ONE WORD.", "answer": "questionnaire", "maxWords": 1, "explanation": "The questionnaire records felt warmth and willingness to choose the route.", "skill": "detail and spelling"}, {"id": "lf4-8", "type": "completion", "prompt": "The sample included few _____. Write NO MORE THAN TWO WORDS.", "answer": "older adults", "maxWords": 2, "explanation": "The college-student sample gives limited evidence about older adults.", "skill": "detail and spelling"}, {"id": "lf4-9", "type": "completion", "prompt": "Planners should pay particular attention to shade at _____. Write NO MORE THAN TWO WORDS.", "answer": "bus stops", "maxWords": 2, "explanation": "People at bus stops may have to remain in one place.", "skill": "detail and spelling"}, {"id": "lf4-10", "type": "completion", "prompt": "Evaluation should include different _____ conditions. Write ONE WORD.", "answer": "weather", "maxWords": 1, "explanation": "Repeated evaluation across weather conditions is more informative than one hot afternoon.", "skill": "detail and spelling"}], "provenance": "Original unofficial IELTS-style practice. Fictional people and scenarios; synthetic recorded voices. Not a calibrated IELTS test.", "durationSeconds": 426.27, "audioLabel": "Prerecorded synthetic voice · Daniel (UK English)", "audioPreparationSeconds": 45, "audioMidpointPreparationSeconds": 45, "audioFinalCheckSeconds": 15}], "provenance": "Original unofficial 40-question practice following the IELTS Listening structure; synthetic recorded voices. Not an official paper or a validated band test.", "source": "https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-listening"}};root.IELTS_LISTENING=content;if(typeof module==='object'&&module.exports)module.exports=content;})(typeof window!=='undefined'?window:globalThis);
